#include <atomic>
#include <chrono>
#include <cstdio>
#include <cstring>
#include <thread>
#include <QCoreApplication>
#include <QTimer>
#include <callback/signal.h>
#include <RecordingShutdownWait.hpp>
int main(int argc, char **argv)
{
    QCoreApplication app(argc, argv);
    const bool never_inactive = argc > 1 && std::strcmp(argv[1], "never-inactive") == 0;
    auto *handler = signal_handler_create();
    signal_handler_add(handler, "void stop(ptr output, int code)");
    signal_handler_add(handler, "void deactivate(ptr output)");
    std::atomic<bool> active{true};
    bool ui_timer_fired = false;
    QObject receiver;
    QTimer::singleShot(50, &receiver, [&] { ui_timer_fired = true; });
    std::thread worker([&] {
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
        uint8_t stack[128];
        calldata_t cd;
        calldata_init_fixed(&cd, stack, sizeof(stack));
        calldata_set_ptr(&cd, "output", nullptr);
        signal_handler_signal(handler, "deactivate", &cd);
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        if (!never_inactive) active = false;
    });
    bool stopped = WaitForOutputToStop(handler, 500, [&] { return active.load(); });
    bool active_at_return = active.load();
    worker.join();
    signal_handler_destroy(handler);
    std::printf("{\"never_inactive\":%s,\"stopped\":%s,\"active_at_return\":%s,\"ui_timer_fired\":%s}\n",
                never_inactive ? "true" : "false", stopped ? "true" : "false",
                active_at_return ? "true" : "false", ui_timer_fired ? "true" : "false");
    return (never_inactive ? (!stopped && active_at_return) : (stopped && !active_at_return)) && ui_timer_fired ? 0 : 1;
}
